REPLACEMENTS.append(('Owner-run real A→B→A Desktop trial on each qualified build: confirm account/workspace in app, preserve outgoing refreshed auth and existing local data; test launch failure.', 'Owner-run real A→B→A Desktop trial on each supported platform: confirm account/workspace in app, preserve outgoing refreshed auth and existing local data; test launch failure. Normal official application updates do not require repeating per-build approval.'))

def transform(text, reverse=False):
    match = MODEL.search(text)
    if match is None:
        raise ValueError("Missing canonical model")
    data = json.loads(match.group(2))
    pairs = [(b, a) for a, b in REPLACEMENTS] if reverse else REPLACEMENTS
    mapping = dict(pairs)
    def walk(value):
        if isinstance(value, str): return mapping.get(value, value)
        if isinstance(value, list): return [walk(v) for v in value]
        if isinstance(value, dict): return {k: walk(v) for k, v in value.items()}
        return value
    data = walk(data)
    data['document_revision'] = 'ca-02-t07-proposal-1' if reverse else REVISION
    data['amendment_status'] = 'proposed_for_owner_review' if reverse else STATUS
    visible = text[:match.start()]
    for old, new in pairs:
        if escape(old) not in visible:
            raise ValueError("Amendment source text differs")
        visible = visible.replace(escape(old), escape(new))
    return visible + match.group(1) + json.dumps(data, ensure_ascii=False, separators=(',', ':')) + match.group(3) + text[match.end():]
